"""core.py -- TASK-20260923-edaa75 blind re-derivation (J4).

Pure-Python-stdlib integer primitives written from the text of
AMD-EXP-AUXIN-7e2e3d-20260923-d1d10 `definitions` only:
  isqrt, icbrt, ceildiv, Baillie-PSW (strong base-2 MR + strong Lucas,
  Selfridge method A), nextprime_ge, nextprime_gt.
No third-party import. Works with Python int (and with gmpy2.mpz by duck typing).
"""
import math

B = 256
M0 = 3 * 2 ** (B - 2)


def isqrt(n):
    x = math.isqrt(int(n))
    assert x * x <= n < (x + 1) * (x + 1)
    return x


def icbrt(n):
    n = int(n)
    assert n >= 0
    if n < 2:
        return n
    # integer Newton iteration from an upper bound
    x = 1 << ((n.bit_length() + 2) // 3 + 1)
    while True:
        y = (2 * x + n // (x * x)) // 3
        if y >= x:
            break
        x = y
    while x * x * x > n:
        x -= 1
    while (x + 1) ** 3 <= n:
        x += 1
    assert x ** 3 <= n < (x + 1) ** 3
    return x


def ceildiv(a, b):
    assert a > 0 and b > 0
    c = -((-a) // b)
    assert c * b >= a and (c - 1) * b < a
    return c


SMALL_PRIMES = [p for p in range(2, 1000) if all(p % q for q in range(2, int(p ** 0.5) + 1))]


def jacobi(a, n):
    assert n > 0 and n % 2 == 1
    a %= n
    result = 1
    while a != 0:
        while a % 2 == 0:
            a //= 2
            r = n % 8
            if r == 3 or r == 5:
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a %= n
    return result if n == 1 else 0


def is_strong_prp_base2(n):
    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1
    x = pow(2, d, n)
    if x == 1 or x == n - 1:
        return True
    for _ in range(s - 1):
        x = x * x % n
        if x == n - 1:
            return True
    return False


def selfridge_D(n):
    """Method A: first D in 5, -7, 9, -11, ... with (D/n) = -1.
    Returns D, or 0 if a D with (D/n) = 0 and |D| != n proves n composite."""
    D = 5
    while True:
        j = jacobi(D, n)
        if j == -1:
            return D
        if j == 0 and abs(D) != n:
            return 0
        D = -D - 2 if D > 0 else -D + 2


def is_strong_lucas_prp(n):
    # perfect squares never yield (D/n) = -1; they are composite
    r = math.isqrt(n)
    if r * r == n:
        return False
    D = selfridge_D(n)
    if D == 0:
        return False
    P = 1
    Q = (1 - D) // 4
    # n + 1 = d * 2^s
    d = n + 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1
    inv2 = (n + 1) // 2  # 2^{-1} mod n, n odd
    # compute U_d, V_d, Q^d by left-to-right binary method
    U, V, Qk = 0, 2, 1  # index 0
    for bit in bin(d)[2:]:
        # double: k -> 2k
        U, V, Qk = (U * V) % n, (V * V - 2 * Qk) % n, (Qk * Qk) % n
        if bit == '1':
            # add one: k -> k + 1
            U, V = ((P * U + V) * inv2) % n, ((D * U + P * V) * inv2) % n
            Qk = (Qk * Q) % n
    if U == 0 or V == 0:
        return True
    for _ in range(s - 1):
        V = (V * V - 2 * Qk) % n
        Qk = (Qk * Qk) % n
        if V == 0:
            return True
    return False


def bpsw(n):
    """Baillie-PSW as defined in the amendment (definitions.prime).
    Trial division by primes < 1000 precedes it (allowed by the text)."""
    n = int(n)
    if n < 2:
        return False
    for p in SMALL_PRIMES:
        if n == p:
            return True
        if n % p == 0:
            return False
    if not is_strong_prp_base2(n):
        return False
    return is_strong_lucas_prp(n)


def nextprime_ge(x, is_prime=bpsw):
    """least prime p >= x, searched upward by +1 (evens > 2 skipped).
    Returns (p, integers_stepped_over_including_p, odd_integers_tested)."""
    x = int(x)
    n = x
    steps = 0
    tested = 0
    while True:
        steps += 1
        if n == 2 or n % 2 == 1:
            tested += 1
            if is_prime(n):
                return n, steps, tested
        n += 1


def nextprime_gt(x, is_prime=bpsw):
    return nextprime_ge(int(x) + 1, is_prime)

certverify.py.source:
"""certverify.py -- stdlib-only primality-certificate verifier written for
TASK-20260923-edaa75. It shares no code with PARI, GMP, FLINT or sympy.

Criteria (published mathematics, provenance: recalled):
 * Pratt / Lucas: N prime iff some a has a^(N-1) = 1 mod N and
   a^((N-1)/f) != 1 mod N for every prime f | N-1 (full factorisation of N-1),
   each f itself certified. [Lucas 1876; Lehmer 1927; Pratt 1975]
 * Pocklington: N-1 = F*R, F > sqrt(N), F fully factored into certified primes,
   a^(N-1) = 1 mod N and gcd(a^((N-1)/f) - 1, N) = 1 for every prime f | F
   => N prime. [Pocklington 1914; Brillhart-Lehmer-Selfridge 1975]
 * ECPP step (Goldwasser-Kilian 1986, Atkin-Morain 1993): gcd(N,6)=1, curve
   y^2 = x^3 + a4 x + b over Z/NZ with gcd(4a4^3+27b^2, N)=1, m = N+1-t, s | m,
   q = m/s, point P with [s]P affine (all denominators units mod N) and
   [q]([s]P) = O, q > (N^(1/4)+1)^2, q prime  =>  N prime.
   Soundness sketch: every checked affine operation mod N reduces to the group
   law mod each prime l | N (l >= 5); so [s]P mod l has order exactly q, hence
   q <= #E(F_l) <= (sqrt(l)+1)^2; a composite N has such l <= sqrt(N),
   contradicting q > (c+1)^2 >= (N^(1/4)+1)^2 where c^4 >= N.
"""
import math


class CertError(Exception):
    pass


def _inv(a, N):
    a %= N
    if math.gcd(a, N) != 1:
        raise CertError('non-invertible denominator mod N')
    return pow(a, -1, N)


def ec_add(P, Q, a4, N):
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if (x1 - x2) % N == 0:
        if (y1 + y2) % N == 0:
            return None
        if (y1 - y2) % N != 0:
            raise CertError('x equal, y neither equal nor opposite mod N')
        lam = (3 * x1 * x1 + a4) * _inv(2 * y1, N) % N
    else:
        lam = (y2 - y1) * _inv(x2 - x1, N) % N
    x3 = (lam * lam - x1 - x2) % N
    y3 = (lam * (x1 - x3) - y1) % N
    return (x3, y3)


def ec_mul(k, P, a4, N):
    R = None
    for bit in bin(k)[2:]:
        R = ec_add(R, R, a4, N)
        if bit == '1':
            R = ec_add(R, P, a4, N)
    return R


def least_c4(N):
    """least integer c with c^4 >= N"""
    c = math.isqrt(math.isqrt(N))
    while c ** 4 < N:
        c += 1
    while c > 0 and (c - 1) ** 4 >= N:
        c -= 1
    return c


def verify_pratt(cert, depth=0):
    """cert = {'p': p} for p == 2, else {'p': p, 'a': a, 'factors': [[f, e, subcert], ...]}"""
    p = cert['p']
    if p == 2:
        return True
    a = cert['a']
    prod = 1
    for f, e, sub in cert['factors']:
        if sub['p'] != f or not (1 < f < p):
            raise CertError('bad factor entry')
        prod *= f ** e
    if prod != p - 1:
        raise CertError('factors do not multiply to p-1 for p=%d' % p)
    if pow(a, p - 1, p) != 1:
        raise CertError('a^(p-1) != 1')
    for f, e, sub in cert['factors']:
        if pow(a, (p - 1) // f, p) == 1:
            raise CertError('a^((p-1)/f) == 1')
        verify_pratt(sub, depth + 1)
    return True


def verify_ecpp(N0, steps, terminal_pratt):
    """steps: list of [N, t, s, a4, [x, y]] (PARI primecert format).
    terminal_pratt: Pratt certificate of the final q. Returns number of steps."""
    if not steps:
        raise CertError('empty chain')
    if steps[0][0] != N0:
        raise CertError('chain does not start at N0')
    for idx, (N, t, s, a4, (x, y)) in enumerate(steps):
        if N <= 1 or math.gcd(N, 6) != 1:
            raise CertError('gcd(N,6) != 1')
        m = N + 1 - t
        if m <= 0 or s <= 0 or m % s:
            raise CertError('s does not divide m')
        q = m // s
        a4 %= N
        x %= N
        y %= N
        b = (y * y - x * x * x - a4 * x) % N
        if math.gcd((4 * a4 ** 3 + 27 * b * b) % N, N) != 1:
            raise CertError('singular curve')
        c = least_c4(N)
        if not q > (c + 1) ** 2:
            raise CertError('q too small')
        Q = ec_mul(s, (x, y), a4, N)
        if Q is None:
            raise CertError('[s]P is the point at infinity')
        R = ec_mul(q, Q, a4, N)
        if R is not None:
            raise CertError('[m]P is not the point at infinity')
        nxt = steps[idx + 1][0] if idx + 1 < len(steps) else terminal_pratt['p']
        if nxt != q:
            raise CertError('next N != q')
    verify_pratt(terminal_pratt)
    return len(steps)


def verify_pocklington_single(N, q, a, q_cert_ok):
    """N - 1 = k * q with q prime (certified elsewhere), q > sqrt(N)."""
    if (N - 1) % q:
        raise CertError('q does not divide N-1')
    if not q * q > N:
        raise CertError('q <= sqrt(N)')
    if pow(a, N - 1, N) != 1:
        raise CertError('a^(N-1) != 1')
    if math.gcd(pow(a, (N - 1) // q, N) - 1, N) != 1:
        raise CertError('gcd(a^((N-1)/q)-1, N) != 1')
    if not q_cert_ok:
        raise CertError('q not certified')
    return True


def verify_lucas_full(N, factors, a, child_ok):
    """Pratt step at N with children certified by any verified method:
    factors = [[f, e], ...] a full factorisation of N-1."""
    prod = 1
    for f, e in factors:
        prod *= f ** e
    if prod != N - 1:
        raise CertError('factors do not multiply to N-1')
    if pow(a, N - 1, N) != 1:
        raise CertError('a^(N-1) != 1')
    for f, e in factors:
        if pow(a, (N - 1) // f, N) == 1:
            raise CertError('a^((N-1)/f) == 1')
        if not child_ok[f]:
            raise CertError('child %d not certified' % f)
    return True


if __name__ == '__main__':
    import ast, sys
    src = open(__file__).read()
    mods = set()
    for node in ast.walk(ast.parse(src)):
        if isinstance(node, ast.Import):
            mods |= {a.name.split('.')[0] for a in node.names}
        elif isinstance(node, ast.ImportFrom):
            mods.add(node.module.split('.')[0])
    print('imports:', sorted(mods), 'stdlib_only:', mods <= set(sys.stdlib_module_names))

certify.py.source:
"""certify.py -- produce primality certificates with PARI/GP (cypari2) and verify
them with the stdlib-only certverify.py. PARI output is untrusted input to the
verifier. Also records PARI isprime(N,2) (APRCL proof) as a separate verdict."""
import json, time, copy
import cypari2
import certverify as cv

pari = cypari2.Pari()
pari.allocatemem(2 * 10 ** 9)
TWO64 = 1 << 64


def pint(x):
    return int(x)


def factor_int(n):
    F = pari.factor(n)
    return [(pint(F[0][i]), pint(F[1][i])) for i in range(len(F[0]))]


def pratt(p, cache={}):
    if p in cache:
        return cache[p]
    if p == 2:
        return {'p': 2}
    fac = factor_int(p - 1)
    a = 2
    while True:
        if pow(a, p - 1, p) == 1 and all(pow(a, (p - 1) // f, p) != 1 for f, _ in fac):
            break
        a += 1
    cert = {'p': p, 'a': a, 'factors': [[f, e, pratt(f)] for f, e in fac]}
    cache[p] = cert
    return cert


def ecpp(N):
    C = pari.primecert(N)
    steps = []
    for st in C:
        steps.append([pint(st[0]), pint(st[1]), pint(st[2]), pint(st[3]), [pint(st[4][0]), pint(st[4][1])]])
    last = steps[-1]
    q_term = (last[0] + 1 - last[1]) // last[2]
    return C, steps, q_term


def certify(N):
    t0 = time.time()
    rec = {'N': N, 'bits': N.bit_length()}
    if N < TWO64:
        c = pratt(N)
        rec['method'] = 'Pratt'
        rec['certificate'] = c
        rec['verifier_accepts'] = cv.verify_pratt(c)
    else:
        C, steps, q_term = ecpp(N)
        tp = pratt(q_term)
        rec['method'] = 'ECPP (PARI primecert chain) + Pratt for terminal prime'
        rec['certificate'] = {'ecpp_steps_[N,t,s,a4,[x,y]]': steps, 'terminal_q': q_term,
                              'terminal_q_bits': q_term.bit_length(), 'terminal_pratt': tp}
        rec['ecpp_chain_length'] = len(steps)
        rec['verifier_accepts'] = cv.verify_ecpp(N, steps, tp) > 0
        rec['pari_primecertisvalid'] = bool(pari.primecertisvalid(C))
    rec['pari_isprime_aprcl'] = bool(pari.isprime(N, 2))
    rec['seconds'] = round(time.time() - t0, 3)
    return rec


def strify(o):
    if isinstance(o, bool):
        return o
    if isinstance(o, int):
        return str(o)
    if isinstance(o, dict):
        return {k: strify(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [strify(v) for v in o]
    return o


out = {'self_tests': {}, 'certificates': {}, 'second_proofs': {}}

# ---- admission-style self-tests of the verifier ----
for label, N in (('2^89-1', 2 ** 89 - 1), ('2^607-1', 2 ** 607 - 1)):
    r = certify(N)
    out['self_tests'][label + '_accepted'] = r['verifier_accepts'] and r['pari_primecertisvalid']
tamper = {}
C, steps, qt = ecpp(2 ** 89 - 1)
bad = copy.deepcopy(steps); bad[0][0] = 2 ** 89 + 1
try:
    cv.verify_ecpp(2 ** 89 + 1, bad, pratt(qt)); tamper['top_N_replaced_by_2^89+1'] = 'ACCEPTED (verifier defect)'
except cv.CertError as e:
    tamper['top_N_replaced_by_2^89+1'] = 'rejected: ' + str(e)
bad = copy.deepcopy(steps); bad[0][4][1] += 1
try:
    cv.verify_ecpp(2 ** 89 - 1, bad, pratt(qt)); tamper['point_y_plus_1'] = 'ACCEPTED (verifier defect)'
except cv.CertError as e:
    tamper['point_y_plus_1'] = 'rejected: ' + str(e)
bad = copy.deepcopy(steps); bad[0][2] *= 3
try:
    cv.verify_ecpp(2 ** 89 - 1, bad, pratt(qt)); tamper['s_times_3'] = 'ACCEPTED (verifier defect)'
except cv.CertError as e:
    tamper['s_times_3'] = 'rejected: ' + str(e)
pc = copy.deepcopy(pratt(1000003)); pc['p'] = 1000005
try:
    cv.verify_pratt(pc); tamper['pratt_p_replaced_composite'] = 'ACCEPTED (verifier defect)'
except cv.CertError as e:
    tamper['pratt_p_replaced_composite'] = 'rejected: ' + str(e)
# composite 561 (Carmichael) with a fake Pratt certificate
fake = {'p': 561, 'a': 2, 'factors': [[2, 4, {'p': 2}], [5, 1, pratt(5)], [7, 1, pratt(7)]]}
try:
    cv.verify_pratt(fake); tamper['pratt_fake_561'] = 'ACCEPTED (verifier defect)'
except cv.CertError as e:
    tamper['pratt_fake_561'] = 'rejected: ' + str(e)
out['self_tests']['tamper'] = tamper

# ---- the control primes ----
S = json.load(open('search_results.json'))
M, P, I = S['C-PLANT-M'], S['C-PLANT-P'], S['C-INERT']
targets = {
    'C-PLANT-M.d1': int(M['d1']), 'C-PLANT-M.d2': int(M['d2']), 'C-PLANT-M.u': int(M['u']),
    'C-PLANT-M.r': int(M['r']), 'C-PLANT-M.v': int(M['v']),
    'C-PLANT-P.d': int(P['d']), 'C-PLANT-P.w': int(P['w']), 'C-PLANT-P.r': int(P['r']), 'C-PLANT-P.q': int(P['q']),
    'C-INERT.w': int(I['w']), 'C-INERT.r': int(I['r']), 'C-INERT.q': int(I['q']),
    'factor_2': 2, 'factor_3': 3,
}
ok = {}
for label, N in targets.items():
    rec = certify(N)
    out['certificates'][label] = rec
    ok[N] = rec['verifier_accepts']
    print(label, N.bit_length(), rec['method'][:5], rec['verifier_accepts'], rec.get('pari_primecertisvalid'),
          rec['pari_isprime_aprcl'], rec['seconds'], flush=True)

# ---- second, ECPP-independent proofs of each r from its constructed N-1 ----
rM = int(M['r']); fM = [[2, 1], [int(M['d1']), 1], [int(M['d2']), 1], [int(M['u']), 1]]
a = 2
while not (pow(a, rM - 1, rM) == 1 and all(pow(a, (rM - 1) // f, rM) != 1 for f, _ in fM)):
    a += 1
out['second_proofs']['C-PLANT-M.r'] = {'method': 'Lucas/Pratt step on r-1 = 2*d1*d2*u (children certified above)',
                                       'a': a, 'verifier_accepts': cv.verify_lucas_full(rM, fM, a, {2: True, **{f: ok[f] for f, _ in fM[1:]}})}
for lab, R, Q in (('C-PLANT-P.r', int(P['r']), int(P['q'])), ('C-INERT.r', int(I['r']), int(I['q']))):
    a = 2
    while not (pow(a, R - 1, R) == 1 and __import__('math').gcd(pow(a, (R - 1) // Q, R) - 1, R) == 1):
        a += 1
    out['second_proofs'][lab] = {'method': 'Pocklington on r-1 = 2*q, q prime > sqrt(r) (q certified above)',
                                 'a': a, 'verifier_accepts': cv.verify_pocklington_single(R, Q, a, ok[Q])}
out['all_verifier_accepts'] = all(ok.values())
json.dump(strify(out), open('certificates.json', 'w'), indent=1)
print(json.dumps(strify(out['self_tests']), indent=1))
print(json.dumps(strify(out['second_proofs']), indent=1))
print('all_verifier_accepts', out['all_verifier_accepts'])

costs.py.source:
"""costs.py -- Q2 (per-branch classification) and Q3 (per-branch typed cost) for
each constructed control, from AMD-EXP-AUXIN-7e2e3d-20260923-d1d10 `definitions`
(typed_costs, analytic_floors_and_ceiling, depth, bins, minimiser_and_ties,
precision) and change.D3_descriptive_bins / D2_typed_costs.

Two independent numeric paths at 210 significant digits:
  path M: mpmath 1.3.0 (mp.dps = 210)
  path D: Python stdlib decimal (prec = 210, Decimal.ln / Decimal.sqrt)
Divisors are enumerated exactly (integers) from the certified factorisations.
"""
import json, itertools, math
from decimal import Decimal, getcontext
import mpmath as mpm

DIG = 210
mpm.mp.dps = DIG
getcontext().prec = DIG

INPUT_MODEL = {
    'minus': 'P, [x]P, [x^d]P (one auxiliary power, exponent d; Cheon 2006 Theorem 1)',
    'plus': '[x^i]P for i = 1..2d (2d consecutive auxiliary powers; Cheon 2006 Theorem 2)',
}


class PathM:
    name = 'mpmath'
    @staticmethod
    def num(n): return mpm.mpf(n)
    @staticmethod
    def sqrt(x): return mpm.sqrt(x)
    @staticmethod
    def log2(x): return mpm.log(x) / mpm.log(2)
    @staticmethod
    def const(p, q): return mpm.mpf(p) / mpm.mpf(q)
    @staticmethod
    def s(x): return mpm.nstr(x, 60, min_fixed=-5, max_fixed=5)


class PathD:
    name = 'decimal'
    @staticmethod
    def num(n): return Decimal(n)
    @staticmethod
    def sqrt(x): return x.sqrt()
    @staticmethod
    def log2(x): return x.ln() / Decimal(2).ln()
    @staticmethod
    def const(p, q): return Decimal(p) / Decimal(q)
    @staticmethod
    def s(x): return format(x, '.60g')


def divisors(fac):
    out = [1]
    for p, e in fac:
        out = [d * p ** k for d in out for k in range(e + 1)]
    return sorted(out)


def evaluate(r, branch, fac, X):
    m = r - 1 if branch == 'minus' else r + 1
    prod = 1
    for p, e in fac:
        prod *= p ** e
    assert prod == m, 'product check failed'
    L = X.log2(X.num(r))
    mX = X.num(m)

    def T(d):
        dX = X.num(d)
        return X.sqrt(mX / dX) + (X.sqrt(dX) if branch == 'minus' else dX)

    divs = divisors(fac)
    vals = [(X.log2(T(d)) / L, d) for d in divs]
    emin = min(v for v, _ in vals)
    tol = X.const(1, 10 ** 100)
    tied = sorted(d for v, d in vals if abs(v - emin) <= tol * abs(emin))
    dmin = tied[0]
    # robustness of the tie rule: nearest non-tied value, relative gap in e and in T
    others = sorted((v, d) for v, d in vals if d not in tied)
    v2, d2 = others[0]
    relgap_e = (v2 - emin) / emin
    relgap_T = (T(d2) - T(dmin)) / T(dmin)
    if branch == 'minus':
        F = (1 + X.log2(X.num(r - 1)) / 4) / L
    else:
        F = (X.log2(X.num(3)) - X.const(2, 3) + X.log2(X.num(r + 1)) / 3) / L
    C = X.log2(X.sqrt(mX) + 1) / L
    s = (C - emin) / (C - F)
    eps = X.const(1, 10 ** 45)
    q1, q3 = X.const(1, 4), X.const(3, 4)
    boundary = abs(s - q1) <= eps or abs(s - q3) <= eps
    if boundary:
        bin_ = 'NEAR_CEILING' if abs(s - q1) <= eps else 'INTERMEDIATE'
    elif s >= q3:
        bin_ = 'NEAR_FLOOR'
    elif s <= q1:
        bin_ = 'NEAR_CEILING'
    else:
        bin_ = 'INTERMEDIATE'
    floor_ok_all = all(v >= F - eps for v, _ in vals)
    tplus_ge_d = all(T(d) >= X.num(d) for d in divs) if branch == 'plus' else None
    Tmin = T(dmin)
    isq = math.isqrt(r)
    ld = max(d for d in divs if d <= isq)
    res = {
        'm_b': m, 'm_b_bits': m.bit_length(), 'factorization': [[p, e] for p, e in fac],
        'status': 'EXACT', 'n_divisors': len(divs),
        'minimiser_d': dmin, 'minimiser_bits': dmin.bit_length(), 'tied_set': tied,
        'log2_T_at_minimiser': X.s(X.log2(Tmin)), 'T_at_minimiser': X.s(Tmin),
        'e_b': X.s(emin), 'F_b': X.s(F), 'C_b': X.s(C),
        'e_minus_F': X.s(emin - F), 'depth_s': X.s(s),
        'bin': bin_, 'boundary_flag': boundary,
        'distance_of_s_to_1/4': X.s(abs(s - q1)), 'distance_of_s_to_3/4': X.s(abs(s - q3)),
        'nearest_non_tied_divisor': d2, 'relative_gap_e_to_nearest_non_tied': X.s(relgap_e),
        'relative_gap_T_to_nearest_non_tied': X.s(relgap_T),
        'floor_invariant_all_divisors_e_ge_F_minus_1e-45': floor_ok_all,
        'input_model': INPUT_MODEL[branch],
        'largest_divisor_le_isqrt_r_bits': ld.bit_length(),
        'log2_r': X.s(L),
    }
    if branch == 'plus':
        res['log2_2d'] = X.s(X.log2(X.num(2 * dmin)))
        res['T_plus_ge_d_all_divisors'] = tplus_ge_d
    raw = {'e': emin, 'F': F, 'C': C, 's': s, 'log2T': X.log2(Tmin)}
    return res, raw


S = json.load(open('search_results.json'))
M, P, I = S['C-PLANT-M'], S['C-PLANT-P'], S['C-INERT']
g = lambda o, k: int(o[k])
controls = {
    'C-PLANT-M': (g(M, 'r'), {'minus': [(2, 1), (g(M, 'd1'), 1), (g(M, 'd2'), 1), (g(M, 'u'), 1)],
                              'plus': [(2, 2), (3, 1), (g(M, 'v'), 1)]}),
    'C-PLANT-P': (g(P, 'r'), {'minus': [(2, 1), (g(P, 'q'), 1)],
                              'plus': [(2, 2), (3, 1), (g(P, 'd'), 1), (g(P, 'w'), 1)]}),
    'C-INERT': (g(I, 'r'), {'minus': [(2, 1), (g(I, 'q'), 1)],
                            'plus': [(2, 2), (3, 1), (g(I, 'w'), 1)]}),
}
out = {}
maxdiff = mpm.mpf(0)
for cid, (r, facs) in controls.items():
    out[cid] = {'r': r, 'r_bits': r.bit_length()}
    for br in ('minus', 'plus'):
        facs[br] = sorted(facs[br])
        resM, rawM = evaluate(r, br, facs[br], PathM)
        resD, rawD = evaluate(r, br, facs[br], PathD)
        agree_exact = all(resM[k] == resD[k] for k in ('minimiser_d', 'tied_set', 'bin', 'boundary_flag', 'status'))
        diffs = {k: abs(rawM[k] - mpm.mpf(str(rawD[k]))) for k in rawM}
        md = max(diffs.values())
        maxdiff = max(maxdiff, md)
        resM['path_D_agrees_exactly_on_minimiser_bin_flag_status'] = agree_exact
        resM['max_abs_diff_path_M_vs_D'] = mpm.nstr(md, 5)
        resM['path_D_values'] = {k: resD[k] for k in ('log2_T_at_minimiser', 'e_b', 'F_b', 'C_b', 'depth_s')}
        out[cid][br] = resM
out['max_abs_diff_all'] = mpm.nstr(maxdiff, 5)
json.dump(out, open('costs.json', 'w'), indent=1, default=str)
for cid in controls:
    for br in ('minus', 'plus'):
        x = out[cid][br]
        print(cid, br, 'd*=', x['minimiser_d'], 'bits', x['minimiser_bits'], x['bin'], 'flag', x['boundary_flag'],
              '\n   log2T', x['log2_T_at_minimiser'][:30], 'e', x['e_b'][:30], 's', x['depth_s'][:25],
              '\n   e-F', x['e_minus_F'][:25], 'relgap_e', x['relative_gap_e_to_nearest_non_tied'][:12],
              'agree', x['path_D_agrees_exactly_on_minimiser_bin_flag_status'], 'maxdiff', x['max_abs_diff_path_M_vs_D'])
print('max_abs_diff_all', out['max_abs_diff_all'])

