"""crosscheck.py -- (1) factor each control m_b with PARI factor() WITHOUT supplying
the construction, and compare the multiset of prime powers with the constructed
factorisation (informational; this is not the amendment's F0-F3 pipeline and
says nothing about its frozen budget, whose value is not in the amendment).
(2) extra tamper tests of certverify on the real control certificates."""
import json, time, copy
import cypari2
import certverify as cv

pari = cypari2.Pari()
pari.allocatemem(2 * 10 ** 9)
S = json.load(open('search_results.json'))
C = json.load(open('certificates.json'))
M, P, I = S['C-PLANT-M'], S['C-PLANT-P'], S['C-INERT']
g = lambda o, k: int(o[k])
cons = {
    'C-PLANT-M': (g(M, 'r'), {'minus': [(2, 1), (g(M, 'd1'), 1), (g(M, 'd2'), 1), (g(M, 'u'), 1)],
                              'plus': [(2, 2), (3, 1), (g(M, 'v'), 1)]}),
    'C-PLANT-P': (g(P, 'r'), {'minus': [(2, 1), (g(P, 'q'), 1)],
                              'plus': [(2, 2), (3, 1), (g(P, 'd'), 1), (g(P, 'w'), 1)]}),
    'C-INERT': (g(I, 'r'), {'minus': [(2, 1), (g(I, 'q'), 1)], 'plus': [(2, 2), (3, 1), (g(I, 'w'), 1)]}),
}
out = {'blind_factor_pari': {}, 'extra_tamper': {}}
for cid, (r, facs) in cons.items():
    for br, m in (('minus', r - 1), ('plus', r + 1)):
        t0 = time.time()
        F = pari.factor(m)
        el = time.time() - t0
        got = sorted((int(F[0][i]), int(F[1][i])) for i in range(len(F[0])))
        out['blind_factor_pari'][cid + '.' + br] = {
            'seconds': round(el, 3), 'equals_constructed_multiset': got == sorted(facs[br]),
            'n_prime_powers': len(got)}
        print(cid, br, round(el, 3), got == sorted(facs[br]), flush=True)


def rd(c):
    return [[int(N), int(t), int(s), int(a4), [int(x), int(y)]] for N, t, s, a4, (x, y) in c]


def pr(d):
    if d['p'] == '2':
        return {'p': 2}
    return {'p': int(d['p']), 'a': int(d['a']), 'factors': [[int(f), int(e), pr(s)] for f, e, s in d['factors']]}


rec = C['certificates']['C-INERT.w']
steps = rd(rec['certificate']['ecpp_steps_[N,t,s,a4,[x,y]]'])
tp = pr(rec['certificate']['terminal_pratt'])
N0 = int(rec['N'])
assert cv.verify_ecpp(N0, steps, tp)
tests = {}
# (a) top N replaced by N0 + 4 (coprime to 6 when N0 = 1 mod 6 or 5 mod 6 shifted suitably)
for delta in (2, 4, 6, 8, 10, 12):
    if __import__('math').gcd(N0 + delta, 6) == 1:
        break
bad = copy.deepcopy(steps); bad[0][0] = N0 + delta
try:
    cv.verify_ecpp(N0 + delta, bad, tp); tests['top_N_plus_%d' % delta] = 'ACCEPTED (defect)'
except cv.CertError as e:
    tests['top_N_plus_%d' % delta] = 'rejected: ' + str(e)
# (b) chain start mismatch
try:
    cv.verify_ecpp(N0 + 2, steps, tp); tests['chain_start_mismatch'] = 'ACCEPTED (defect)'
except cv.CertError as e:
    tests['chain_start_mismatch'] = 'rejected: ' + str(e)
# (c) drop the last step (next N != q)
if len(steps) > 1:
    try:
        cv.verify_ecpp(N0, steps[:-1], tp); tests['drop_last_step'] = 'ACCEPTED (defect)'
    except cv.CertError as e:
        tests['drop_last_step'] = 'rejected: ' + str(e)
# (d) t changed by 2
bad = copy.deepcopy(steps); bad[0][1] += 2
try:
    cv.verify_ecpp(N0, bad, tp); tests['t_plus_2'] = 'ACCEPTED (defect)'
except cv.CertError as e:
    tests['t_plus_2'] = 'rejected: ' + str(e)
# (e) a composite N = product of two ~128-bit primes posed with the real chain's step 0 data
import gmpy2
pA = int(gmpy2.next_prime(2 ** 126 + 12345)); pB = int(gmpy2.next_prime(2 ** 126 + 99999))
bad = copy.deepcopy(steps); bad[0][0] = pA * pB
try:
    cv.verify_ecpp(pA * pB, bad, tp); tests['composite_top_N'] = 'ACCEPTED (defect)'
except cv.CertError as e:
    tests['composite_top_N'] = 'rejected: ' + str(e)
# (f) Pratt of terminal prime with wrong witness a=1
bad = copy.deepcopy(tp); bad['a'] = 1
try:
    cv.verify_pratt(bad); tests['pratt_witness_1'] = 'ACCEPTED (defect)'
except cv.CertError as e:
    tests['pratt_witness_1'] = 'rejected: ' + str(e)
out['extra_tamper'] = tests
print(json.dumps(tests, indent=1))
json.dump(out, open('crosscheck.json', 'w'), indent=1)

