"""tamper2.py -- tamper cases that keep s | m, so rejection must come from the
elliptic-curve arithmetic ([m]P != O) or the chain link, not from divisibility."""
import json, copy
import certverify as cv
C = json.load(open('certificates.json'))
def rd(c): return [[int(N), int(t), int(s), int(a4), [int(x), int(y)]] for N, t, s, a4, (x, y) in c]
def pr(d):
    if d['p'] == '2': return {'p': 2}
    return {'p': int(d['p']), 'a': int(d['a']), 'factors': [[int(f), int(e), pr(s)] for f, e, s in d['factors']]}
res = {}
for lab in ('C-INERT.w', 'C-PLANT-M.r', 'C-PLANT-P.q'):
    rec = C['certificates'][lab]; N0 = int(rec['N'])
    st = rd(rec['certificate']['ecpp_steps_[N,t,s,a4,[x,y]]']); tp = pr(rec['certificate']['terminal_pratt'])
    assert cv.verify_ecpp(N0, st, tp)
    for name, mut in (('t_plus_s', lambda b: b[0].__setitem__(1, b[0][1] + b[0][2])),
                      ('a4_plus_1', lambda b: b[0].__setitem__(3, b[0][3] + 1)),
                      ('x_plus_1', lambda b: b[0][4].__setitem__(0, b[0][4][0] + 1))):
        bad = copy.deepcopy(st); mut(bad)
        try:
            cv.verify_ecpp(N0, bad, tp); res[lab + '.' + name] = 'ACCEPTED (defect)'
        except cv.CertError as e:
            res[lab + '.' + name] = 'rejected: ' + str(e)
print(json.dumps(res, indent=1))
json.dump(res, open('tamper2.json', 'w'), indent=1)

